SELECT *, AVG(status_bits) OVER (PARTITION BY device_code ORDER BY temp_c ASC, id ASC ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS status_bits_avg_3, NTILE(10) OVER (PARTITION BY device_code ORDER BY pressure ASC, id ASC) AS pressure_bucket, FIRST_VALUE(temp_c) IGNORE NULLS OVER (PARTITION BY device_code ORDER BY humidity ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_temp_c FROM device_readings;
